import{_ as e,c as a,o as t,a0 as n}from"./chunks/framework.DKRgXLPU.js";const i=JSON.parse('{"title":"Inleiding tot het mentale spel - Dia&#39;s voor de begeleider","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/nl/facilitator-slides.md","filePath":"public/downloads/nl/facilitator-slides.md"}');const r=e({name:"public/downloads/nl/facilitator-slides.md"},[["render",function(e,i,r,o,l,s){return t(),a("div",null,[...i[0]||(i[0]=[n('<h1 id="inleiding-tot-het-mentale-spel-dia-39-s-voor-de-begeleider" tabindex="-1">Inleiding tot het mentale spel - Dia&#39;s voor de begeleider <a class="header-anchor" href="#inleiding-tot-het-mentale-spel-dia-39-s-voor-de-begeleider" aria-label="Permalink to &quot;Inleiding tot het mentale spel - Dia&amp;#39;s voor de begeleider&quot;">​</a></h1><p><strong>Pétanque Academie</strong><em>Sessiehandleiding voor begeleiders</em></p><hr><h2 id="dia-1-welkom" tabindex="-1">Dia 1: Welkom <a class="header-anchor" href="#dia-1-welkom" aria-label="Permalink to &quot;Dia 1: Welkom&quot;">​</a></h2><h1 id="🎯-introductie-van-het-mentale-spel" tabindex="-1">🎯 Introductie van het mentale spel <a class="header-anchor" href="#🎯-introductie-van-het-mentale-spel" aria-label="Permalink to &quot;🎯 Introductie van het mentale spel&quot;">​</a></h1><p><strong>Voor Elite-petanquespelers</strong></p><h3 id="vandaag-ontdek-je" tabindex="-1">Vandaag ontdek je: <a class="header-anchor" href="#vandaag-ontdek-je" aria-label="Permalink to &quot;Vandaag ontdek je:&quot;">​</a></h3><ul><li>🧠 Hoe creëer je de juiste omstandigheden voor &quot;de zone&quot;?</li><li>💪 Hoe je je innerlijke criticus het zwijgen oplegt</li><li>🎪 Praktische hulpmiddelen die onder druk presteren</li></ul><p><strong>Maak je klaar voor een interactieve sessie!</strong></p><hr><h2 id="dia-2-snelle-peiling-wie-is-het-ermee-eens-🙋" tabindex="-1">Dia 2: Snelle peiling - Wie is het ermee eens? 🙋 <a class="header-anchor" href="#dia-2-snelle-peiling-wie-is-het-ermee-eens-🙋" aria-label="Permalink to &quot;Dia 2: Snelle peiling - Wie is het ermee eens? 🙋&quot;">​</a></h2><h3 id="wie-heeft-dit-meegemaakt" tabindex="-1">Wie heeft dit meegemaakt? <a class="header-anchor" href="#wie-heeft-dit-meegemaakt" aria-label="Permalink to &quot;Wie heeft dit meegemaakt?&quot;">​</a></h3><p><strong>Steek je hand op als je ooit:</strong></p><ol><li><p>Een perfecte worp tijdens de training... en vervolgens mis in de wedstrijd? 🎯❌</p></li><li><p>Had je het gevoel dat je gedachten alle kanten op schoten terwijl je juist rustig moest blijven? 🧠💨</p></li><li><p>Heb je jezelf bekritiseerd na een fout? 😤</p></li><li><p>Heb je wel eens een game gespeeld waarbij alles gewoon op zijn plek viel? ✨</p></li></ol><p><strong>Je bent niet alleen! Laten we dit samen oplossen.</strong></p><hr><h2 id="dia-3-de-paradox-van-de-topspeler" tabindex="-1">Dia 3: De paradox van de topspeler <a class="header-anchor" href="#dia-3-de-paradox-van-de-topspeler" aria-label="Permalink to &quot;Dia 3: De paradox van de topspeler&quot;">​</a></h2><h3 id="je-hebt-de-vaardigheden-al-dus-waarom-zou-je-het-niet-doen" tabindex="-1">Je hebt de vaardigheden al... Dus waarom zou je het niet doen? <a class="header-anchor" href="#je-hebt-de-vaardigheden-al-dus-waarom-zou-je-het-niet-doen" aria-label="Permalink to &quot;Je hebt de vaardigheden al... Dus waarom zou je het niet doen?&quot;">​</a></h3><p><strong>✅ Je hebt:</strong></p><ul><li>Uitstekende techniek (duizenden uren)</li><li>Jarenlange ervaring</li><li>Fysieke bekwaamheid</li></ul><p><strong>❌ Maar je hebt moeite met:</strong></p><ul><li>Die techniek toepassen onder druk</li><li>Consistent blijven in de competitie</li><li>Na fouten weer opkrabbelen</li></ul><h3 id="het-ontbrekende-stukje-🧩" tabindex="-1">Het ontbrekende stukje? 🧩 <a class="header-anchor" href="#het-ontbrekende-stukje-🧩" aria-label="Permalink to &quot;Het ontbrekende stukje? 🧩&quot;">​</a></h3><p><strong>Jouw mentale spel.</strong></p><p><em>&quot;Het verschil tussen goed en geweldig zit hem in wat er tussen je oren gebeurt.&quot;</em></p><hr><h2 id="dia-4-de-zone-je-kent-dit-gevoel-wel-⚡" tabindex="-1">Dia 4: De Zone - Je kent dit gevoel wel! ⚡ <a class="header-anchor" href="#dia-4-de-zone-je-kent-dit-gevoel-wel-⚡" aria-label="Permalink to &quot;Dia 4: De Zone - Je kent dit gevoel wel! ⚡&quot;">​</a></h2><h3 id="weet-je-nog-die-perfecte-wedstrijd" tabindex="-1">Weet je nog, die perfecte wedstrijd? <a class="header-anchor" href="#weet-je-nog-die-perfecte-wedstrijd" aria-label="Permalink to &quot;Weet je nog, die perfecte wedstrijd?&quot;">​</a></h3><p><strong>Alles voelde als:</strong></p><ul><li>⏱️ De tijd vertraagde</li><li>🎯 Moeiteloos en automatisch</li><li>🧘 Volledig geconcentreerd</li><li>🎪 Alsof je dit niet kon missen</li></ul><h3 id="dat-is-quot-de-zone-quot-flowtoestand" tabindex="-1">Dat is &quot;De Zone&quot; (Flowtoestand). <a class="header-anchor" href="#dat-is-quot-de-zone-quot-flowtoestand" aria-label="Permalink to &quot;Dat is &amp;quot;De Zone&amp;quot; (Flowtoestand).&quot;">​</a></h3><p><strong>De vraag:</strong><em>Hoe krijgen we er consistent toegang toe, en niet alleen per ongeluk?</em></p><p><strong>Het antwoord:</strong><em>Inzicht in je twee denkmodi...</em></p><hr><h2 id="dia-5-je-hersenen-hebben-twee-standen-🧠" tabindex="-1">Dia 5: Je hersenen hebben twee standen 🧠 <a class="header-anchor" href="#dia-5-je-hersenen-hebben-twee-standen-🧠" aria-label="Permalink to &quot;Dia 5: Je hersenen hebben twee standen 🧠&quot;">​</a></h2><h3 id="🤔-planningsmodus-analytisch-brein" tabindex="-1">🤔 PLANNINGSMODUS (Analytisch brein) <a class="header-anchor" href="#🤔-planningsmodus-analytisch-brein" aria-label="Permalink to &quot;🤔 PLANNINGSMODUS (Analytisch brein)&quot;">​</a></h3><p><strong>Wanneer te gebruiken:</strong> VÓÓR de opname</p><ul><li>📊 Analyse van het terrein</li><li>🎯 Je strategie kiezen</li><li>⚖️ De risico&#39;s afwegen</li><li>🤝 De keuze voor de foto</li></ul><h3 id="🎯-uitvoeringsmodus-flow-brain" tabindex="-1">🎯 UITVOERINGSMODUS (Flow Brain) <a class="header-anchor" href="#🎯-uitvoeringsmodus-flow-brain" aria-label="Permalink to &quot;🎯 UITVOERINGSMODUS (Flow Brain)&quot;">​</a></h3><p><strong>Wanneer te gebruiken:</strong> TIJDENS de opname</p><ul><li>💪 Vertrouw op je lichaam</li><li>🚫 NIET nadenken over de techniek</li><li>⏰ Alleen het huidige moment</li><li>🤖 Automatische prestaties</li></ul><h3 id="⚠️-het-probleem" tabindex="-1">⚠️ HET PROBLEEM: <a class="header-anchor" href="#⚠️-het-probleem" aria-label="Permalink to &quot;⚠️ HET PROBLEEM:&quot;">​</a></h3><p><strong>De meeste spelers blijven tijdens de uitvoering in de planningsmodus!</strong><em>Je analytische brein verstoort je automatische prestaties.</em></p><hr><h2 id="dia-6-de-schakelaar-jouw-geheime-wapen-🔄" tabindex="-1">Dia 6: De schakelaar - Jouw geheime wapen 🔄 <a class="header-anchor" href="#dia-6-de-schakelaar-jouw-geheime-wapen-🔄" aria-label="Permalink to &quot;Dia 6: De schakelaar - Jouw geheime wapen 🔄&quot;">​</a></h2><h3 id="beheers-deze-ene-vaardigheid" tabindex="-1">Beheers deze ene vaardigheid: <a class="header-anchor" href="#beheers-deze-ene-vaardigheid" aria-label="Permalink to &quot;Beheers deze ene vaardigheid:&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BEFORE the shot:          DURING the shot:</span></span>\n<span class="line"><span>🤔 Planning Mode    →     🎯 Execution Mode</span></span></code></pre></div><h3 id="het-proces" tabindex="-1">Het proces: <a class="header-anchor" href="#het-proces" aria-label="Permalink to &quot;Het proces:&quot;">​</a></h3><p><strong>1️⃣ VOOR (10-15 seconden):</strong></p><ul><li>🤔 Analyseer alles</li><li>📊 Plan je strategie</li><li>✅ Neem je beslissing</li></ul><p><strong>2️⃣ DE OVERGANG (3 ademhalingen):</strong></p><ul><li>🌬️ Adem diep in en uit</li><li>🧘 Maak je hoofd leeg</li><li>🔄 Laat de analyse los</li></ul><p><strong>3️⃣ GEDURENDE (2-3 seconden):</strong></p><ul><li>🎯 Vertrouw volledig</li><li>🤖 Laat het gebeuren</li><li>⚡ Automatisch uitvoeren</li></ul><p><strong>Oefen deze schakelaar = Toegang tot de gegevensstroom op aanvraag!</strong></p><hr><h2 id="dia-7-activiteit-probeer-het-nu-🎯" tabindex="-1">Dia 7: ACTIVITEIT - Probeer het nu! 🎯 <a class="header-anchor" href="#dia-7-activiteit-probeer-het-nu-🎯" aria-label="Permalink to &quot;Dia 7: ACTIVITEIT - Probeer het nu! 🎯&quot;">​</a></h2><h3 id="laten-we-de-switch-oefenen-2-minuten" tabindex="-1">Laten we de switch oefenen (2 minuten) <a class="header-anchor" href="#laten-we-de-switch-oefenen-2-minuten" aria-label="Permalink to &quot;Laten we de switch oefenen (2 minuten)&quot;">​</a></h3><p><strong>Iedereen opstaan!</strong></p><ol><li><p><strong>Planningsmodus (10 sec):</strong> Stel je voor dat je een schot analyseert. Denk na over het terrein, de strategie en de risico&#39;s.</p></li><li><p><strong>De Omschakeling (3 ademhalingen):</strong> Haal drie keer diep adem. Maak je hoofd leeg bij elke uitademing.</p></li><li><p><strong>Uitvoeringsmodus (3 sec):</strong> Stel je voor dat je gooit. Niet nadenken. Gewoon vertrouwen en meegaan met de stroom.</p></li></ol><p><strong>Hoe voelde dat? Anders?</strong></p><p><em>Ga zitten en laten we het bespreken...</em></p><hr><h2 id="dia-8-maak-kennis-met-je-innerlijke-criticus-😈" tabindex="-1">Dia 8: Maak kennis met je innerlijke criticus 😈 <a class="header-anchor" href="#dia-8-maak-kennis-met-je-innerlijke-criticus-😈" aria-label="Permalink to &quot;Dia 8: Maak kennis met je innerlijke criticus 😈&quot;">​</a></h2><h3 id="klinkt-deze-stem-bekend" tabindex="-1">Klinkt deze stem bekend? <a class="header-anchor" href="#klinkt-deze-stem-bekend" aria-label="Permalink to &quot;Klinkt deze stem bekend?&quot;">​</a></h3><p><strong>Na een mislukte worp:</strong></p><ul><li>💢 &quot;Dat was VERSCHRIKKELIJK!&quot;</li><li>😤 &quot;Je maakt ALTIJD fouten onder druk!&quot;</li><li>😰 &quot;Iedereen kijkt toe hoe je faalt!&quot;</li><li>😞 &quot;Je bent gewoon niet goed genoeg!&quot;</li></ul><h3 id="snelle-peiling-🙋" tabindex="-1">Snelle peiling: 🙋 <a class="header-anchor" href="#snelle-peiling-🙋" aria-label="Permalink to &quot;Snelle peiling: 🙋&quot;">​</a></h3><p><strong>Wie hoort deze stem regelmatig?</strong></p><h3 id="de-waarheid" tabindex="-1">De waarheid: <a class="header-anchor" href="#de-waarheid" aria-label="Permalink to &quot;De waarheid:&quot;">​</a></h3><p><strong>Je innerlijke criticus probeert je te helpen...</strong><em>Maar het ondermijnt juist je prestaties.</em></p><hr><h2 id="dia-9-ontsla-je-criticus-neem-je-coach-in-dienst-🔄" tabindex="-1">Dia 9: Ontsla je criticus, neem je coach in dienst! 🔄 <a class="header-anchor" href="#dia-9-ontsla-je-criticus-neem-je-coach-in-dienst-🔄" aria-label="Permalink to &quot;Dia 9: Ontsla je criticus, neem je coach in dienst! 🔄&quot;">​</a></h2><h3 id="de-transformatie" tabindex="-1">De transformatie: <a class="header-anchor" href="#de-transformatie" aria-label="Permalink to &quot;De transformatie:&quot;">​</a></h3><table tabindex="0"><thead><tr><th>😈 Innerlijke Criticus</th><th>➡️</th><th>😊 Innerlijke Coach</th></tr></thead><tbody><tr><td>&quot;Je verknoeit het ALTIJD!&quot;</td><td>→</td><td>&quot;Ik heb deze foto al duizend keer eerder gemaakt&quot;</td></tr><tr><td>&quot;Dat was VERSCHRIKKELIJK!&quot;</td><td>→</td><td>&quot;Wat kan ik hiervan leren?&quot;</td></tr><tr><td>&quot;Iedereen oordeelt over je!&quot;</td><td>→</td><td>&quot;Focus op MIJN spel, niet op hun meningen&quot;</td></tr><tr><td>&quot;Je bent niet goed genoeg!&quot;</td><td>→</td><td>&quot;Ik word elke dag beter&quot;</td></tr></tbody></table><h3 id="de-impact" tabindex="-1">De impact: <a class="header-anchor" href="#de-impact" aria-label="Permalink to &quot;De impact:&quot;">​</a></h3><p><strong>Kritiek = Angst, spanning, slechte prestaties</strong><strong>Coach = Zelfvertrouwen, ontspanning, topprestaties</strong></p><hr><h2 id="dia-10-activiteit-herformuleer-je-criticus-💬" tabindex="-1">Dia 10: ACTIVITEIT - Herformuleer je criticus! 💬 <a class="header-anchor" href="#dia-10-activiteit-herformuleer-je-criticus-💬" aria-label="Permalink to &quot;Dia 10: ACTIVITEIT - Herformuleer je criticus! 💬&quot;">​</a></h2><h3 id="partneroefening-3-minuten" tabindex="-1">Partneroefening (3 minuten) <a class="header-anchor" href="#partneroefening-3-minuten" aria-label="Permalink to &quot;Partneroefening (3 minuten)&quot;">​</a></h3><p><strong>Draai je om naar de persoon naast je:</strong></p><p><strong>Persoon A (1,5 min):</strong></p><ol><li>Deel één ding dat je innerlijke criticus zegt.</li><li>Partner helpt je het te herformuleren als Innerlijke Coach</li><li>Schrijf de nieuwe zin op.</li></ol><p><strong>Persoon B (1,5 min):</strong></p><ol><li>Hetzelfde proces</li><li>Deel je gedachten over je innerlijke criticus.</li><li>Vraag hulp om het in een ander perspectief te plaatsen.</li></ol><p><strong>Klaar? Start!</strong></p><p><em>We zullen daarna een paar voorbeelden met de groep delen...</em></p><hr><h2 id="dia-11-hulpmiddel-nr-1-de-reset-met-3-ademhalingen-🌬️" tabindex="-1">Dia 11: Hulpmiddel nr. 1 - De reset met 3 ademhalingen 🌬️ <a class="header-anchor" href="#dia-11-hulpmiddel-nr-1-de-reset-met-3-ademhalingen-🌬️" aria-label="Permalink to &quot;Dia 11: Hulpmiddel nr. 1 - De reset met 3 ademhalingen 🌬️&quot;">​</a></h2><h3 id="uw-noodontlastingsklep" tabindex="-1">Uw noodontlastingsklep <a class="header-anchor" href="#uw-noodontlastingsklep" aria-label="Permalink to &quot;Uw noodontlastingsklep&quot;">​</a></h3><p><strong>Gebruik dit wanneer:</strong></p><ul><li>😤 Je hebt net een fout gemaakt.</li><li>😰 Je voelt de druk toenemen</li><li>🤯 Je gedachten razen door je hoofd.</li></ul><h3 id="het-proces-1" tabindex="-1">Het proces: <a class="header-anchor" href="#het-proces-1" aria-label="Permalink to &quot;Het proces:&quot;">​</a></h3><p><strong>🌬️ ADEMHALING 1 (4 seconden inademen):</strong> Let op waar je spanning voelt (schouders? kaak? buik?).</p><p><strong>🌬️ ADEMHALING 2 (6 seconden uitademen):</strong> Laat die spanning los. Laat het met je ademhaling wegvloeien.</p><p><strong>🌬️ ADEMHALING 3 (4 keer inademen, 6 keer uitademen):</strong> Richt je aandacht op het NU. Deze foto. Dit moment. Niets anders.</p><p><strong>⏱️ Duurt 20 seconden. Verandert alles.</strong></p><hr><h2 id="dia-12-demo-iedereen-mag-het-proberen-🌬️" tabindex="-1">Dia 12: DEMO - Iedereen mag het proberen! 🌬️ <a class="header-anchor" href="#dia-12-demo-iedereen-mag-het-proberen-🌬️" aria-label="Permalink to &quot;Dia 12: DEMO - Iedereen mag het proberen! 🌬️&quot;">​</a></h2><h3 id="_3-ademhaling-reset-oefening-1-minuut" tabindex="-1">3-ademhaling reset oefening (1 minuut) <a class="header-anchor" href="#_3-ademhaling-reset-oefening-1-minuut" aria-label="Permalink to &quot;3-ademhaling reset oefening (1 minuut)&quot;">​</a></h3><p><strong>Iedereen even de ogen dichtdoen...</strong></p><p><strong>Ademhaling 1:</strong><em>Adem 4 seconden in... Waar voel je spanning?</em></p><p><strong>Ademhaling 2:</strong><em>Adem 6 seconden uit... Laat het los...</em></p><p><strong>Ademhaling 3:</strong><em>Ingewijd voor 4, uit voor 6... Alleen het hier en nu...</em></p><p><strong>Open je ogen. Hoe voel je je?</strong></p><p><em>Dit is je resetknop. Gebruik hem!</em></p><hr><h2 id="dia-13-hulpmiddel-2-je-voorbereidingsroutine-🎯" tabindex="-1">Dia 13: Hulpmiddel #2 - Je voorbereidingsroutine 🎯 <a class="header-anchor" href="#dia-13-hulpmiddel-2-je-voorbereidingsroutine-🎯" aria-label="Permalink to &quot;Dia 13: Hulpmiddel #2 - Je voorbereidingsroutine 🎯&quot;">​</a></h2><h3 id="zorg-voor-automatische-consistentie" tabindex="-1">Zorg voor automatische consistentie <a class="header-anchor" href="#zorg-voor-automatische-consistentie" aria-label="Permalink to &quot;Zorg voor automatische consistentie&quot;">​</a></h3><p><strong>De routine in 4 stappen:</strong></p><p><strong>1️⃣ VISUALISEER (3 seconden)</strong> Stel je het perfecte schot voor. Zie hoe de bal precies terechtkomt waar je hem wilt hebben.</p><p><strong>2️⃣ ADEMHALING (2 seconden)</strong> Haal diep adem. Schakel over van de planningsmodus naar de uitvoeringsmodus.</p><p><strong>3️⃣ ANKER (2 seconden)</strong> Raak je boule aan. Voel het gewicht. De fysieke verbinding.</p><p><strong>4️⃣ UITVOEREN (2 seconden)</strong> Vertrouw volledig. Laat je lichaam doen wat het weet.</p><p><strong>⏱️ Totaal: 9 seconden. Elke keer hetzelfde.</strong></p><h3 id="waarom-het-werkt" tabindex="-1">Waarom het werkt: <a class="header-anchor" href="#waarom-het-werkt" aria-label="Permalink to &quot;Waarom het werkt:&quot;">​</a></h3><p><strong>Consistentie = Vertrouwen = Prestatie</strong></p><hr><h2 id="dia-14-hulpmiddel-3-protocol-voor-foutcorrectie-🔄" tabindex="-1">Dia 14: Hulpmiddel #3 - Protocol voor foutcorrectie 🔄 <a class="header-anchor" href="#dia-14-hulpmiddel-3-protocol-voor-foutcorrectie-🔄" aria-label="Permalink to &quot;Dia 14: Hulpmiddel #3 - Protocol voor foutcorrectie 🔄&quot;">​</a></h2><h3 id="een-mislukte-worp-hier-is-je-herstel-in-4-stappen" tabindex="-1">Een mislukte worp? Hier is je herstel in 4 stappen: <a class="header-anchor" href="#een-mislukte-worp-hier-is-je-herstel-in-4-stappen" aria-label="Permalink to &quot;Een mislukte worp? Hier is je herstel in 4 stappen:&quot;">​</a></h3><p><strong>1️⃣ BEVESTIGING (2 seconden)</strong> &quot;Dat liep niet zoals gepland.&quot; (Geen oordeel, gewoon een constatering)</p><p><strong>2️⃣ LOSLATEN (3 seconden)</strong> Fysieke reset: Schud je handen, rol je schouders, loop 3 stappen.</p><p><strong>3️⃣ HERKANTELEN (3 seconden)</strong> &quot;De volgende foto is een NIEUWE kans.&quot; (Niet gerelateerd aan de vorige)</p><p><strong>4️⃣ UITVOEREN (Gebruik je routine)</strong> Vertrouw op je voorbereiding. Een frisse start.</p><h3 id="het-belangrijkste-inzicht" tabindex="-1">Het belangrijkste inzicht: <a class="header-anchor" href="#het-belangrijkste-inzicht" aria-label="Permalink to &quot;Het belangrijkste inzicht:&quot;">​</a></h3><p><strong>Elke opname is onafhankelijk. Maak geen fouten en neem ze niet mee naar de volgende.</strong></p><p><em>De beste spelers hebben het kortste geheugen voor slechte slagen.</em></p><hr><h2 id="dia-15-eerlijk-gesprek-wat-houdt-je-tegen-💬" tabindex="-1">Dia 15: EERLIJK GESPREK - Wat houdt je tegen? 💬 <a class="header-anchor" href="#dia-15-eerlijk-gesprek-wat-houdt-je-tegen-💬" aria-label="Permalink to &quot;Dia 15: EERLIJK GESPREK - Wat houdt je tegen? 💬&quot;">​</a></h2><h3 id="groepsdiscussie-5-minuten" tabindex="-1">Groepsdiscussie (5 minuten) <a class="header-anchor" href="#groepsdiscussie-5-minuten" aria-label="Permalink to &quot;Groepsdiscussie (5 minuten)&quot;">​</a></h3><p><strong>We horen graag van u:</strong></p><p><strong>Vraag 1:</strong><em>&quot;Wanneer ervaar je het meest een flow-ervaring? Welke omstandigheden helpen daarbij?&quot;</em></p><p><strong>Vraag 2:</strong><em>&quot;Wat is jouw grootste mentale uitdaging tijdens een wedstrijd?&quot;</em></p><p><strong>Vraag 3:</strong><em>&quot;Welk van deze tools spreekt jou het meest aan?&quot;</em></p><ul><li>3-ademhaling reset</li><li>Voorbereidingsroutine</li><li>Innerlijke coach herformulering</li><li>Foutherstel</li></ul><p><strong>Deel je ervaringen gerust - dit is een veilige plek!</strong></p><hr><h2 id="dia-16-jouw-actieplan-kies-er-een-✅" tabindex="-1">Dia 16: Jouw actieplan - Kies er ÉÉN! ✅ <a class="header-anchor" href="#dia-16-jouw-actieplan-kies-er-een-✅" aria-label="Permalink to &quot;Dia 16: Jouw actieplan - Kies er ÉÉN! ✅&quot;">​</a></h2><h3 id="de-uitdaging-van-deze-week" tabindex="-1">De uitdaging van deze week: <a class="header-anchor" href="#de-uitdaging-van-deze-week" aria-label="Permalink to &quot;De uitdaging van deze week:&quot;">​</a></h3><p><strong>Kies SLECHTS ÉÉN techniek om te oefenen:</strong></p><p><strong>Optie A: 🌬️ Reset met 3 ademhalingen</strong> Gebruik na ELKE fout tijdens de training.</p><p><strong>Optie B: 🎯 Voorbereidingsroutine</strong> Dezelfde routine van 4 stappen bij ELKE worp.</p><p><strong>Optie C: 💬 Innerlijke Coach</strong> Herformuleer ÉÉN kritische gedachte per sessie.</p><p><strong>Optie D: 🔄 Moduswisseling</strong> Oefenplanning → uitvoeringsomschakeling</p><h3 id="waarom-maar-een" tabindex="-1">Waarom maar één? <a class="header-anchor" href="#waarom-maar-een" aria-label="Permalink to &quot;Waarom maar één?&quot;">​</a></h3><p><strong>Beheers eerst één gereedschap voordat je een ander probeert.</strong><em>Diepte is belangrijker dan breedte bij mentale training.</em></p><hr><h2 id="dia-17-houd-je-voortgang-bij-📊" tabindex="-1">Dia 17: Houd je voortgang bij 📊 <a class="header-anchor" href="#dia-17-houd-je-voortgang-bij-📊" aria-label="Permalink to &quot;Dia 17: Houd je voortgang bij 📊&quot;">​</a></h2><h3 id="wat-valt-er-deze-week-op-te-merken" tabindex="-1">Wat valt er deze week op te merken? <a class="header-anchor" href="#wat-valt-er-deze-week-op-te-merken" aria-label="Permalink to &quot;Wat valt er deze week op te merken?&quot;">​</a></h3><p><strong>🎯 Flow-momenten:</strong></p><ul><li>Wanneer voelde je je &quot;in de flow&quot;?</li><li>Hoe laat is het?</li><li>Wat voor soort schot?</li><li>Wat heeft je geholpen om daar te komen?</li></ul><p><strong>💪 Succesvolle techniek:</strong></p><ul><li>Welk hulpmiddel werkte het beste?</li><li>Wanneer heb je het gebruikt?</li><li>Wat was de uitkomst?</li></ul><p><strong>📝 Houd een eenvoudig logboek bij:</strong><em>&quot;Reset met 3 ademhalingen na een fout → voelde me rustiger → maakte de volgende opname&quot;</em></p><h3 id="het-doel" tabindex="-1">Het doel: <a class="header-anchor" href="#het-doel" aria-label="Permalink to &quot;Het doel:&quot;">​</a></h3><p><strong>Ontdek JOUW patronen. Bouw JOUW systeem.</strong></p><hr><h2 id="dia-18-vervolg-je-reis-🚀" tabindex="-1">Dia 18: Vervolg je reis 🚀 <a class="header-anchor" href="#dia-18-vervolg-je-reis-🚀" aria-label="Permalink to &quot;Dia 18: Vervolg je reis 🚀&quot;">​</a></h2><h3 id="gratis-bronnen-op-carreau-app" tabindex="-1">Gratis bronnen op carreau.app: <a class="header-anchor" href="#gratis-bronnen-op-carreau-app" aria-label="Permalink to &quot;Gratis bronnen op carreau.app:&quot;">​</a></h3><p><strong>📚 Diepgaande analyses:</strong></p><ul><li><strong>De Zone</strong> - Beheers flow-toestanden</li><li><strong>Mentale kracht</strong> - Geavanceerd omgaan met druk</li><li><strong>Teamdynamiek</strong> - Communicatie en vertrouwen</li><li><strong>Mindfulness</strong> - Focus op het huidige moment</li></ul><p><strong>🛠️ Praktische hulpmiddelen:</strong></p><ul><li><strong>Doelsjabloon</strong> - Structureer uw ontwikkeling</li><li><strong>Dagboeksjabloon</strong> - Houd je dagelijkse voortgang bij</li><li><strong>Workshophandleiding</strong> - Organiseer je eigen sessies</li></ul><p><strong>Volledig gratis. Volledig toegankelijk. Volledig ontworpen voor topspelers.</strong></p><hr><h2 id="dia-19-de-4-belangrijkste-ideeen-💡" tabindex="-1">Dia 19: De 4 belangrijkste ideeën 💡 <a class="header-anchor" href="#dia-19-de-4-belangrijkste-ideeen-💡" aria-label="Permalink to &quot;Dia 19: De 4 belangrijkste ideeën 💡&quot;">​</a></h2><h3 id="neem-deze-mee-naar-huis" tabindex="-1">Neem deze mee naar huis: <a class="header-anchor" href="#neem-deze-mee-naar-huis" aria-label="Permalink to &quot;Neem deze mee naar huis:&quot;">​</a></h3><p><strong>1️⃣ Flow is een VAARDIGHEID, geen geluk</strong> Je kunt leren hoe je er op aanvraag toegang toe krijgt.</p><p><strong>2️⃣ Je innerlijke stem VORMT je prestaties</strong> Coach jezelf, bekritiseer jezelf niet.</p><p><strong>3️⃣ Eenvoudige tools werken onder druk</strong> Drie keer ademhalen. Een routine. Een reset. Dat is alles.</p><p><strong>4️⃣ Oefening baart kunst</strong> Mentale vaardigheden vereisen training, net als technische vaardigheden.</p><h3 id="de-waarheid-1" tabindex="-1">De waarheid: <a class="header-anchor" href="#de-waarheid-1" aria-label="Permalink to &quot;De waarheid:&quot;">​</a></h3><p><strong>Mentale training is niet mystiek. Het is praktisch.</strong></p><hr><h2 id="dia-20-vragen-laten-we-praten-💬" tabindex="-1">Dia 20: Vragen? Laten we praten! 💬 <a class="header-anchor" href="#dia-20-vragen-laten-we-praten-💬" aria-label="Permalink to &quot;Dia 20: Vragen? Laten we praten! 💬&quot;">​</a></h2><h1 id="open-discussie" tabindex="-1">Open discussie <a class="header-anchor" href="#open-discussie" aria-label="Permalink to &quot;Open discussie&quot;">​</a></h1><p><strong>Welke vragen heb je?</strong></p><p><strong>Welke ervaringen wilt u delen?</strong></p><p><strong>Welke uitdagingen ondervindt u?</strong></p><p><strong>Wat ga je als eerste proberen?</strong></p><p><em>Dit is JOUW sessie. Laten we er samen voor zorgen dat het waardevol voor JOU is.</em></p><hr><h2 id="dia-21-jouw-uitdaging-🎯" tabindex="-1">Dia 21: Jouw uitdaging 🎯 <a class="header-anchor" href="#dia-21-jouw-uitdaging-🎯" aria-label="Permalink to &quot;Dia 21: Jouw uitdaging 🎯&quot;">​</a></h2><h1 id="de-missie-van-deze-week" tabindex="-1">De missie van deze week: <a class="header-anchor" href="#de-missie-van-deze-week" aria-label="Permalink to &quot;De missie van deze week:&quot;">​</a></h1><p><strong>1️⃣ Kies ÉÉN gereedschap</strong> (3-ademhaling reset, voorbereidingsroutine, innerlijke coach of moduswisseling)</p><p><strong>2️⃣ Oefen het ELKE sessie</strong> (Consistentie wint het van intensiteit)</p><p><strong>3️⃣ Let op welke veranderingen er zijn</strong> (Houd je voortgang bij)</p><p><strong>4️⃣ Deel je resultaten</strong> (Met je trainingspartners of op carreau.app)</p><h3 id="herinneren" tabindex="-1">Herinneren: <a class="header-anchor" href="#herinneren" aria-label="Permalink to &quot;Herinneren:&quot;">​</a></h3><p><strong>Kleine veranderingen → Grote resultaten</strong></p><hr><h2 id="dia-22-dankjewel-🙏" tabindex="-1">Dia 22: Dankjewel! 🙏 <a class="header-anchor" href="#dia-22-dankjewel-🙏" aria-label="Permalink to &quot;Dia 22: Dankjewel! 🙏&quot;">​</a></h2><h1 id="dit-kun-je" tabindex="-1">Dit kun je! <a class="header-anchor" href="#dit-kun-je" aria-label="Permalink to &quot;Dit kun je!&quot;">​</a></h1><p><strong>Wat je vandaag hebt geleerd:</strong></p><ul><li>✅ Hoe krijg ik toegang tot stroomtoestanden?</li><li>✅ Hoe je je innerlijke criticus in toom houdt</li><li>✅ Praktische hulpmiddelen die onder druk presteren</li><li>✅ Een duidelijk actieplan voor deze week</li></ul><p><strong>Volgende stappen:</strong></p><ol><li>Kies ÉÉN techniek</li><li>Oefen het consequent.</li><li>Bezoek carreau.app voor meer informatie.</li><li>Deel je voortgang met de groep.</li></ol><h3 id="de-reis-begint-nu" tabindex="-1">De reis begint nu: <a class="header-anchor" href="#de-reis-begint-nu" aria-label="Permalink to &quot;De reis begint nu:&quot;">​</a></h3><p><strong>Mentale training is praktisch, niet mystiek.</strong><strong>Begin vandaag nog. Zie snel resultaat.</strong></p><hr><p><em>Pétanque Academie - Ontwikkeling van elitespelers</em><em>carreau.app - Gratis hulpmiddelen voor topspelers</em></p>',201)])])}]]);export{i as __pageData,r as default};
